#include <stdio.h>
#include <string.h>

static double capacity;
static double refill_rate;
static double tokens;
static double last;
static int has_last = 0;

static void do_init(double cap, double rate) {
    capacity = cap;
    refill_rate = rate;
    tokens = cap;
    has_last = 0;
}

static int do_allow(double now) {
    if (has_last) {
        double elapsed = now - last;
        tokens += elapsed * refill_rate;
        if (tokens > capacity) tokens = capacity;
    }
    last = now;
    has_last = 1;
    if (tokens >= 1.0) {
        tokens -= 1.0;
        return 1;
    }
    return 0;
}

int main(void) {
    char cmd[16];
    double a, b;
    while (scanf("%15s", cmd) == 1) {
        if (strcmp(cmd, "init") == 0) {
            if (scanf("%lf %lf", &a, &b) == 2) do_init(a, b);
        } else if (strcmp(cmd, "allow") == 0) {
            if (scanf("%lf", &a) == 1) printf("%d\n", do_allow(a));
        }
    }
    return 0;
}

